WITH my_cte AS (
  SELECT one, two
  FROM my_table
)
SELECT *
FROM my_cte;

WITH first AS (
  INSERT INTO my_table (one, two)
  VALUES (1, 2)
  RETURNING *
), second AS (
  SELECT one, two
  FROM my_table
)
SELECT *
FROM second;

WITH first AS NOT MATERIALIZED (
  SELECT a FROM b
), second AS MATERIALIZED (
  SELECT one, two
  FROM my_table
)
SELECT *
FROM second;

WITH top_cte AS (
  WITH nested_cte AS (
    SELECT 1 as one, 2 as two
  )
  SELECT one, two
  FROM nested_cte
)
SELECT *
FROM top_cte;

WITH top_cte AS (
  WITH nested_cte AS (
    WITH nested_further AS (
      SELECT 1 as one, 2 as two
    )
    SELECT * FROM nested_further
  )
  SELECT one, two
  FROM nested_cte
)
SELECT *
FROM top_cte;

